package org.zuma.examplePlugin.domain.heads;

import org.bukkit.inventory.ItemStack;

public enum HeadTexture {
    BRONZE_HELM(""),
    IRON_HELM(""),
    STEEL_HELM(""),
    MITHRIL_HELM(""),
    ADAMANT_HELM(""),
    RUNE_HELM("");

    private final String base64;

    HeadTexture(String base64) {
        this.base64 = base64;
    }

    public String asBase64() {
        return this.base64;
    }

    public ItemStack asItemStack() {
        return HeadGenerator.createHead(this.base64);
    }
}
